graphql.query:
{
  posts(page: 0, size: 5) {
    totalElements
    totalPages
    content { id title author { username } tags { name } }
  }
}

query ($id: ID!) {
  post(id: $id) { title tags { name } }
  comments(postId: $id, size: 5) { totalElements content { body authorName } }
  reviews(postId: $id) { rating text }
}
